/** The compliance register — GET /api/v1/facility/compliance-documents (who may call: holders of facility.view or facility.compliance.manage or blood.bank.manage). */
export function listDocumentsFacilityCompliance(query?: { kind?: "Licence" | "Registration" | "Certificate" | "Plan" | "Law" | null; category?: "Hospital" | "Radiation" | "Building" | "Fire" | "Lift" | "Boiler" | "Power" | "BloodTransfusion" | "Food" | "Waste" | "Pharmacy" | "Laboratory" | "Water" | "Environment" | "Emergency" | "Equipment" | "Staff" | "Other" | null; state?: "Valid" | "DueForRenewal" | "Expired" | "NoExpiry" | null; responsible_user_id?: number | null; include_closed?: boolean }): Promise<ComplianceDocumentOut[]> {
  return api<ComplianceDocumentOut[]>("GET", withQuery(`/facility/compliance-documents`, query), undefined);
}

/** Add a licence, certificate, plan or law to the register — POST /api/v1/facility/compliance-documents (who may call: holders of facility.compliance.manage). */
export function addDocument(body: ComplianceDocumentIn): Promise<ComplianceDocumentDetailOut> {
  return api<ComplianceDocumentDetailOut>("POST", `/facility/compliance-documents`, body, { idempotent: true });
}

/** One entry of the register, with the entries it renewed — GET /api/v1/facility/compliance-documents/{document_id} (who may call: holders of facility.view or facility.compliance.manage). */
export function getDocument(document_id: number): Promise<ComplianceDocumentDetailOut> {
  return api<ComplianceDocumentDetailOut>("GET", `/facility/compliance-documents/${document_id}`, undefined);
}

/** Correct an entry, or record that its renewal is applied for — PUT /api/v1/facility/compliance-documents/{document_id} (who may call: holders of facility.compliance.manage). */
export function updateDocument(document_id: number, body: ComplianceDocumentUpdateIn): Promise<ComplianceDocumentDetailOut> {
  return api<ComplianceDocumentDetailOut>("PUT", `/facility/compliance-documents/${document_id}`, body);
}

/** Record the renewal (or the amendment) — POST /api/v1/facility/compliance-documents/{document_id}/renew (who may call: holders of facility.compliance.manage). */
export function renewDocument(document_id: number, body: ComplianceRenewIn): Promise<ComplianceDocumentDetailOut> {
  return api<ComplianceDocumentDetailOut>("POST", `/facility/compliance-documents/${document_id}/renew`, body, { idempotent: true });
}

/** Withdraw an entry no longer needed — POST /api/v1/facility/compliance-documents/{document_id}/withdraw (who may call: holders of facility.compliance.manage). */
export function withdrawDocument(document_id: number, body: ComplianceWithdrawIn): Promise<ComplianceDocumentDetailOut> {
  return api<ComplianceDocumentDetailOut>("POST", `/facility/compliance-documents/${document_id}/withdraw`, body, { idempotent: true });
}

/** Attach the scan (PDF or image) — POST /api/v1/facility/compliance-documents/{document_id}/scan (who may call: holders of facility.compliance.manage). */
export function uploadScan(document_id: number, body: FormData): Promise<ComplianceDocumentDetailOut> {
  return api<ComplianceDocumentDetailOut>("POST", `/facility/compliance-documents/${document_id}/scan`, body, { idempotent: true });
}

